package kz.zeroops.api;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.time.*; import java.util.*; import org.springframework.http.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1/agent") public class AgentController {
 private final EnrollmentTokenRepository enrollments; private final ManagedServerRepository servers; private final ServerHeartbeatRepository heartbeats; private final DeploymentRepository deployments; private final DeploymentLogRepository logs; private final ProjectRepository projects; private final ProjectServiceRepository services; private final ManifestSigner manifests; private final java.security.SecureRandom random=new java.security.SecureRandom();
 public AgentController(EnrollmentTokenRepository enrollments,ManagedServerRepository servers,ServerHeartbeatRepository heartbeats,DeploymentRepository deployments,DeploymentLogRepository logs,ProjectRepository projects,ProjectServiceRepository services,ManifestSigner manifests){this.enrollments=enrollments;this.servers=servers;this.heartbeats=heartbeats;this.deployments=deployments;this.logs=logs;this.projects=projects;this.services=services;this.manifests=manifests;}
 @PostMapping("/enroll") public AgentCredential enroll(@Valid @RequestBody EnrollRequest request){EnrollmentToken token=enrollments.findByTokenHash(ServerController.hash(request.token())).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Enrollment token is invalid"));if(!token.active())throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Enrollment token is expired, used or revoked");ManagedServer s=token.getServer();String raw=secret();s.setAgentTokenHash(ServerController.hash(raw));s.status(ServerStatus.OFFLINE);servers.save(s);token.use();enrollments.save(token);return new AgentCredential(s.getId(),raw,Instant.now().plus(Duration.ofDays(30)));}
 @PostMapping("/{id}/heartbeat") @ResponseStatus(HttpStatus.NO_CONTENT) public void heartbeat(@PathVariable Long id,@RequestHeader("X-Agent-Token") String credential,@Valid @RequestBody HeartbeatRequest r){ManagedServer s=servers.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Server not found"));if(s.getAgentTokenHash()==null||!java.security.MessageDigest.isEqual(s.getAgentTokenHash().getBytes(),ServerController.hash(credential).getBytes()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Agent credential is invalid");if(s.getStatus()==ServerStatus.DISABLED)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Server is disabled");heartbeats.save(new ServerHeartbeat(s,r.cpuPercent(),r.ramPercent(),r.diskPercent(),r.managedContainers(),r.dockerVersion(),r.os(),r.agentVersion()));s.seen();servers.save(s);}
 @GetMapping("/{id}/deployments/next") @Transactional public ResponseEntity<ManifestSigner.SignedManifest> next(@PathVariable Long id,@RequestHeader("X-Agent-Token") String credential){ManagedServer s=authenticated(id,credential);if(s.getStatus()!=ServerStatus.ONLINE)throw new ResponseStatusException(HttpStatus.CONFLICT,"Server is not available");requeueExpiredLeases(id);return deployments.findQueuedForServer(id).stream().findFirst().map(d->{ManifestSigner.SignedManifest manifest=manifests.issue(d);d.moveTo(DeploymentStatus.CHECKOUT);deployments.save(d);appendLog(d,"Deployment leased to enrolled Agent; awaiting verified execution.");return ResponseEntity.ok(manifest);}).orElseGet(()->ResponseEntity.noContent().build());}
 @PostMapping("/{serverId}/deployments/{deploymentId}/result") @ResponseStatus(HttpStatus.NO_CONTENT) @Transactional public void result(@PathVariable Long serverId,@PathVariable Long deploymentId,@RequestHeader("X-Agent-Token") String credential,@Valid @RequestBody ResultRequest r){authenticated(serverId,credential);Deployment d=deployments.findWithProjectAndOwnerById(deploymentId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Deployment not found"));if(d.getProject().getTargetServer()==null||!d.getProject().getTargetServer().getId().equals(serverId))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Deployment belongs to another server");if(d.getStatus()==DeploymentStatus.SUCCESS||d.getStatus()==DeploymentStatus.FAILED) return;if(r.success()&&r.applicationPort()!=null&&r.publicPort()!=null&&r.runtime()!=null&&r.healthPath()!=null){try{ProjectRuntime runtime=ProjectRuntime.valueOf(r.runtime());if(r.applicationPort()<1||r.applicationPort()>65535||r.publicPort()<18100||r.publicPort()>18999||!r.healthPath().matches("/[A-Za-z0-9._~/%?-]{0,255}"))throw new IllegalArgumentException();d.getProject().applyAgentResolvedConfiguration(runtime,r.applicationPort(),r.publicPort(),r.healthPath());projects.save(d.getProject());}catch(IllegalArgumentException invalid){throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Agent returned an invalid resolved deployment configuration");}}d.moveTo(r.success()?DeploymentStatus.SUCCESS:DeploymentStatus.FAILED,r.success()?null:r.reason());deployments.save(d);appendLog(d,r.message());}
 @PostMapping("/{serverId}/deployments/{deploymentId}/logs") @ResponseStatus(HttpStatus.NO_CONTENT) @Transactional public void ingestLogs(@PathVariable Long serverId,@PathVariable Long deploymentId,@RequestHeader("X-Agent-Token") String credential,@Valid @RequestBody AgentLogsRequest request){authenticated(serverId,credential);Deployment d=deployments.findWithProjectAndOwnerById(deploymentId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Deployment not found"));if(d.getProject().getTargetServer()==null||!d.getProject().getTargetServer().getId().equals(serverId))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Deployment belongs to another server");for(String message:request.messages())appendLog(d,message);}
 @PostMapping("/{serverId}/deployments/{deploymentId}/plan") @ResponseStatus(HttpStatus.NO_CONTENT) @Transactional public void ingestPlan(@PathVariable Long serverId,@PathVariable Long deploymentId,@RequestHeader("X-Agent-Token") String credential,@Valid @RequestBody AgentPlanRequest request){authenticated(serverId,credential);Deployment d=deployments.findWithProjectAndOwnerById(deploymentId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Deployment not found"));Project p=d.getProject();if(p.getTargetServer()==null||!p.getTargetServer().getId().equals(serverId))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Deployment belongs to another server");services.deleteAll(services.findByProjectIdOrderByCreatedAtAsc(p.getId()));for(ServicePlanItem item:request.services()){ProjectRuntime runtime;try{runtime=ProjectRuntime.valueOf(item.runtime());}catch(Exception bad){throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Agent reported unsupported runtime");}if(!item.path().matches("(?:\\.|[A-Za-z0-9._/-]{1,200})")||item.path().contains("..")||item.port()<1||item.port()>65535)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Agent reported an invalid service plan");services.save(new ProjectService(p,item.key(),item.path(),runtime,item.port(),item.publicCandidate()?ServiceVisibility.PUBLIC:ServiceVisibility.PRIVATE,item.hasDockerfile()?DockerfileSource.REPOSITORY:DockerfileSource.GENERATED,item.path().equals(d.getServicePath()),String.join(",",item.evidence())));}}
 private ManagedServer authenticated(Long id,String credential){ManagedServer s=servers.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Server not found"));if(s.getAgentTokenHash()==null||!java.security.MessageDigest.isEqual(s.getAgentTokenHash().getBytes(),ServerController.hash(credential).getBytes()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Agent credential is invalid");return s;}
 private void requeueExpiredLeases(Long serverId){Instant now=Instant.now();Instant before=now.minus(Duration.ofMinutes(3));Set<DeploymentStatus> active=Set.of(DeploymentStatus.CHECKOUT,DeploymentStatus.ANALYZING,DeploymentStatus.BUILDING,DeploymentStatus.DEPLOYING,DeploymentStatus.HEALTH_CHECKING);for(Deployment deployment:deployments.findExpiredLeasesForServer(serverId,active,before,now.minus(Duration.ofHours(24)))){deployment.requeueExpiredLease();appendLog(deployment,"Agent lease expired after 3 minutes; deployment was safely returned to the queue.");}}
 private synchronized void appendLog(Deployment deployment,String message){int line=logs.maxLineNumber(deployment.getId())+1;logs.saveAndFlush(new DeploymentLog(deployment,line,message));}
 private String secret(){byte[] b=new byte[32];random.nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);} public record EnrollRequest(@NotBlank String token){} public record AgentCredential(Long serverId,String credential,Instant expiresAt){} public record HeartbeatRequest(@Min(0) @Max(100) int cpuPercent,@Min(0) @Max(100) int ramPercent,@Min(0) @Max(100) int diskPercent,@Min(0) int managedContainers,@Size(max=100) String dockerVersion,@Size(max=100) String os,@Size(max=100) String agentVersion){} public record ResultRequest(boolean success,@NotBlank @Size(max=1000) String message,@Size(max=1000) String reason,@Min(1) @Max(65535) Integer applicationPort,@Min(18100) @Max(18999) Integer publicPort,@Pattern(regexp="NODE|SPRING_BOOT|PYTHON|GO|DOTNET|DOCKERFILE") String runtime,@Pattern(regexp="/[A-Za-z0-9._~/%?-]{0,255}") String healthPath){} public record AgentLogsRequest(@NotEmpty @Size(max=100) List<@NotBlank @Size(max=1000) String> messages){} public record AgentPlanRequest(@NotEmpty @Size(max=30) List<@Valid ServicePlanItem> services){} public record ServicePlanItem(@NotBlank @Pattern(regexp="[a-z0-9-]{1,100}") String key,@NotBlank String path,@NotBlank String runtime,@Min(1) @Max(65535) int port,boolean publicCandidate,boolean hasDockerfile,@Size(max=10) List<@NotBlank @Size(max=100) String> evidence){}
}
